import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"UI Revamp v0 — Inspiration References","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/prd/ui-revamp-v0-refs.md","filePath":"architecture/prd/ui-revamp-v0-refs.md","lastUpdated":1780254295000}'),i={name:"architecture/prd/ui-revamp-v0-refs.md"};function n(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-revamp-v0-—-inspiration-references" tabindex="-1">UI Revamp v0 — Inspiration References <a class="header-anchor" href="#ui-revamp-v0-—-inspiration-references" aria-label="Permalink to &quot;UI Revamp v0 — Inspiration References&quot;">​</a></h1><p>Companion to <a href="./ui-revamp-v0">ui-revamp-v0.md</a>. Findings from a Refero pass against real product UIs. Each section maps to a PRD flow / component, calls out what to <strong>borrow</strong>, and what to <strong>avoid</strong>.</p><p>This doc is not a design — it&#39;s a kit of references for the lock pass that follows.</p><h2 id="_1-three-pane-workspace-prd-§3-layout" tabindex="-1">1. Three-pane workspace (PRD §3 layout) <a class="header-anchor" href="#_1-three-pane-workspace-prd-§3-layout" aria-label="Permalink to &quot;1. Three-pane workspace (PRD §3 layout)&quot;">​</a></h2><h3 id="borrow" tabindex="-1">Borrow <a class="header-anchor" href="#borrow" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Hello Ivy</strong> (<a href="https://refero.design/pages/b578cdd7-1063-45c5-a26e-4a9cd6c9a750" target="_blank" rel="noreferrer">screen b578cdd7</a>). 52px icon-only spaces rail on the far left, a second narrow column for the page tree (Pages: Meeting notes / Pitch deck), then the document, then a contextual right panel (&quot;Change design / Typography preview / Font family&quot;). This is exactly the four-column shape we want. Notably the right panel is <strong>single-purpose and contextual</strong> — it appeared because the user invoked a typography action — rather than a permanent &quot;chat pane&quot;. That matches our §3 panel-stack model: panels are slots, opened on demand.</li><li><strong>Slab</strong> (<a href="https://refero.design/pages/74b6ec78-2918-478a-b293-b48ef0dfccc0" target="_blank" rel="noreferrer">screen 74b6ec78</a>). Reference for the <strong>collapsed</strong> state of the spaces/pages rail: the entire left becomes a thin column of just-icons (search, menu) and the editor takes everything. Confirms our §3 &quot;tight&quot; mode is realistic, not aspirational.</li></ul><h3 id="avoid" tabindex="-1">Avoid <a class="header-anchor" href="#avoid" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li>Hello Ivy chips: feature-card pills with <code>Archia / Basier Circle / Lato …</code> are nice but each chip is double-bordered (border + selection ring). We don&#39;t need both. Use a single-border resting state, then a fill on selected — keeps density.</li><li>Slab&#39;s top action bar has <code>Saved · Editing · Read · Share · ⋯ · Publish</code> plus an avatar. Five separate controls for one workflow. We want this as a single split-button + overflow.</li></ul><h2 id="_2-right-area-panel-system-prd-§3-right-area-§4-5-chat" tabindex="-1">2. Right-area panel system (PRD §3 right area, §4.5 chat) <a class="header-anchor" href="#_2-right-area-panel-system-prd-§3-right-area-§4-5-chat" aria-label="Permalink to &quot;2. Right-area panel system (PRD §3 right area, §4.5 chat)&quot;">​</a></h2><h3 id="borrow-1" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-1" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Rox</strong> (<a href="https://refero.design/pages/438aaaec-9a74-4104-99a5-46ba8fececc5" target="_blank" rel="noreferrer">screen 438aaaec</a>). Closest match to our model. Left column is a chat/notes flow (&quot;Five innovative ideas to improve the OpenAI project&quot;, with inline avatar-mention chips for Peter Welinder, Ryan Beiermeister, Rikki Gorman, Sanj Bhayro). Right column is a <em>contextual record</em> — &quot;New Opportunity&quot; with fields stacked vertically (Owner, Stage, Close Date, Associated People, Tags, Next Step). The two columns scroll independently and the right one has its own header (<code>OpenAI</code> + Overview / Account Report / Activity / Notes tabs).</li><li>The Rox composer is a <strong>single rounded input</strong> with a small chip row beneath: <code>+ · OpenAI ↕ · Command can make mistakes</code>. The <code>OpenAI ↕</code> chip is the pattern we want for the §4.5 icon-only backend switcher — small, low-contrast, lives in the composer footer not a giant header bar.</li></ul><h3 id="avoid-1" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-1" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li>Rox&#39;s modal-on-top-of-side-sheet pattern (the &quot;New Opportunity&quot; sheet is essentially a modal pretending to be a panel). Our panels are <strong>not modal</strong> — they&#39;re independently usable surfaces.</li><li>Two parallel scroll regions side-by-side with no visual divider — Rox relies on subtle bg shifts, but our denser layout will need a clear 1px divider, no shadow.</li></ul><h2 id="_3-mention-picker-prd-§4-5-§4-6" tabindex="-1">3. Mention picker (PRD §4.5, §4.6) <a class="header-anchor" href="#_3-mention-picker-prd-§4-5-§4-6" aria-label="Permalink to &quot;3. Mention picker (PRD §4.5, §4.6)&quot;">​</a></h2><h3 id="borrow-2" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-2" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li>The inline avatar-pill rendering in Rox: a mention renders as a tiny rounded pill with the avatar and name, slightly recessed background. We extend this for bots: <code>@bot:foo</code> should be a similar pill with a <strong>bot mark</strong> (different icon, slightly different surface) so users can visually distinguish bot mentions from user/doc mentions at a glance. This is critical because bot mentions cause command dispatch, not chat.</li><li>The mention list pattern (across many screens we surveyed): sectioned by entity type, with avatar/icon + primary text + faint secondary text. Sections we need: <ol><li><strong>Bots</strong> (most important — surfaces only this space&#39;s bots; bot mentions are routed to the bot runtime, not the LLM)</li><li><strong>Documents</strong> (pages within this space)</li><li><strong>Members</strong> (people in this space)</li></ol></li><li>Keep the picker keyboard-driven first. Arrow keys move within a section, then jump to the next section&#39;s first item. Esc closes.</li></ul><h3 id="avoid-2" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-2" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li>Slack&#39;s emoji-heavy mention rows. Our chat is for productivity, not banter — keep typography uniform.</li><li>ChatGPT-style &quot;@&quot; chips in the composer that double as commands (<code>Search</code>, <code>Attach</code>). We want <strong>two distinct surfaces</strong>: a slash menu for editor/system commands, an @ menu for entity references. Don&#39;t conflate them.</li></ul><h2 id="_4-bot-adding-flow-—-paste-peer-address-prd-§4-4" tabindex="-1">4. Bot-adding flow — paste peer address (PRD §4.4) <a class="header-anchor" href="#_4-bot-adding-flow-—-paste-peer-address-prd-§4-4" aria-label="Permalink to &quot;4. Bot-adding flow — paste peer address (PRD §4.4)&quot;">​</a></h2><h3 id="borrow-3" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-3" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Wise — Create an API token</strong> (<a href="https://refero.design/pages/f8fc84dc-b7cb-4284-bc24-a0a0f3611412" target="_blank" rel="noreferrer">screen f8fc84dc</a>). Single screen, three fields total: name, two radio options for permission profile (<code>Full access</code> vs <code>Read only</code>, each with one-line subtext), and a single optional field (<code>Allowed IPs</code>). That is a great floor for our §4.4 step 2 (capability grant). It proves a credential issue UI can be <em>one screen, three fields</em>, not a wizard.</li><li><strong>Appwrite — Key details</strong> (<a href="https://refero.design/pages/bed87b22-1d30-418e-b975-45daab6b1e5c" target="_blank" rel="noreferrer">screen bed87b22</a>). Cards: Key details (Name, Expiration date, Last accessed, Secret), Name (editable), then Scopes block grouped by domain (Auth, Database, …) each collapsible with a &quot;5 Scopes / 0 Scopes&quot; counter. This is the right pattern when there are many possible scopes — grouped + counted + collapsed. Use it for our space-resource scopes (docs / messages / attachments / pages / etc.).</li></ul><h3 id="synthesis-our-§4-4-inline-form" tabindex="-1">Synthesis: our §4.4 inline form <a class="header-anchor" href="#synthesis-our-§4-4-inline-form" aria-label="Permalink to &quot;Synthesis: our §4.4 inline form&quot;">​</a></h3><ul><li><strong>Step 1</strong> (paste): single oversized monospace text input, validate on blur, show parsed peer-id + alias preview underneath. Borrow the Wise pattern&#39;s tightness.</li><li><strong>Step 2</strong> (grant): Appwrite-style cards, all visible on one scroll surface: <ul><li><strong>Identity</strong> — peer id (read-only), alias used in <code>@bot:&lt;alias&gt;</code></li><li><strong>Scopes</strong> — collapsible groups (Documents / Messages / Attachments / Membership), each with <code>n granted of m</code> count; expand to see per-scope checkboxes</li><li><strong>Expiry</strong> — date picker, with quick presets (7d, 30d, 90d, never if owner)</li><li><strong>Issue</strong> — single primary action; surface handshake errors right above it, not in a toast</li></ul></li></ul><h3 id="avoid-3" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-3" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li>Multi-step modals like Twitter &quot;Pick a list&quot; (we surveyed several variants) — they imply a catalog, but our bots <strong>are not in a catalog</strong>: every bot is identified by a peer address pasted by the inviter.</li><li>Confirmation dialogs that ask the user to retype the bot name. We have signature + scope; redundant text entry just slows the path.</li><li>Floating CTAs (Wise puts the create button bottom-right of the modal, fine for a modal; for our inline form the action belongs at the bottom of the scroll, not floating).</li></ul><h2 id="_5-acp-backend-switcher-in-chat-header-prd-§4-5" tabindex="-1">5. ACP backend switcher in chat header (PRD §4.5) <a class="header-anchor" href="#_5-acp-backend-switcher-in-chat-header-prd-§4-5" aria-label="Permalink to &quot;5. ACP backend switcher in chat header (PRD §4.5)&quot;">​</a></h2><h3 id="borrow-4" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-4" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>ChatGPT home composer</strong> (<a href="https://refero.design/pages/874de703-27cd-4c0b-b06c-ed47dcace2b7" target="_blank" rel="noreferrer">screen 874de703</a>). Rounded composer with chip-style action buttons (<code>📎 Attach</code>, <code>🌐 Search</code>, <code>🎙 Voice</code>) inline. Surfaces affordances without taking vertical space. Use this aesthetic for our composer chips.</li><li>The Rox composer&#39;s <code>OpenAI ↕</code> chip (mentioned above) is the <strong>specific</strong> pattern for the model picker — provider mark + chevron, opens a dropdown with text labels.</li></ul><h3 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>The PRD says &quot;icon-only with dropdown&quot; in the chat <em>header</em>. Refero pass argues moving it from the header into the <strong>composer footer</strong> (Rox + ChatGPT both do this). The composer footer is where the user is looking when they decide which backend to send to. Moving it there removes a header element entirely. Recommend updating §4.5 in the lock pass.</p><h3 id="avoid-4" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-4" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li>Bard/Gemini-style large model bar across the top of every message. Eats vertical space we don&#39;t have on 14&quot; laptops.</li><li>Pinning the picker to a global app header. The backend is a per-message decision; the control belongs near the input.</li></ul><h2 id="_6-capability-scope-grant-patterns-reviewed-but-rejected" tabindex="-1">6. Capability/scope grant patterns reviewed but rejected <a class="header-anchor" href="#_6-capability-scope-grant-patterns-reviewed-but-rejected" aria-label="Permalink to &quot;6. Capability/scope grant patterns reviewed but rejected&quot;">​</a></h2><ul><li><strong>Pinterest business member dialog</strong> — multi-step modal with role selection then permissions then send invite. We don&#39;t need this much ceremony; a peer-address paste isn&#39;t an email invite.</li><li><strong>Doppler &quot;Welcome to workplace&quot; gradient onboarding</strong> — heavy art direction, no relevance.</li><li><strong>n8n dark sign-up form</strong> — gives us no signal for in-app capability grants.</li></ul><p>These are listed so the lock pass doesn&#39;t re-discover them.</p><h2 id="_7-pattern-locks-recommendations-for-adr-0005" tabindex="-1">7. Pattern locks (recommendations for ADR-0005) <a class="header-anchor" href="#_7-pattern-locks-recommendations-for-adr-0005" aria-label="Permalink to &quot;7. Pattern locks (recommendations for ADR-0005)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>PRD ref</th><th>Pattern locked from refs</th><th>Reference</th></tr></thead><tbody><tr><td>§3 layout</td><td>52px icon spaces rail + narrow page-tree column + document + right panel-stack, with a per-panel header containing only a title + collapse + close (no shadow)</td><td>Hello Ivy b578cdd7</td></tr><tr><td>§3 collapsed state</td><td>Spaces rail + page tree both collapse to a single thin column of icons in &quot;tight&quot; mode</td><td>Slab 74b6ec78</td></tr><tr><td>§4.4 step 1</td><td>Single oversized text input, paste peer address, validate on blur, show parsed identity preview underneath</td><td>(Wise minimalism applied to a peer-id paste)</td></tr><tr><td>§4.4 step 2</td><td>Appwrite-style scoped cards on one scroll surface: Identity / Scopes (collapsible groups with counts) / Expiry / Issue</td><td>Appwrite bed87b22</td></tr><tr><td>§4.5 backend switcher</td><td>Move from chat-header to composer footer chip: <code>&lt;provider-mark&gt; &lt;name&gt; ↕</code>, dropdown with text labels and &quot;Add backend…&quot; footer item</td><td>Rox 438aaaec composer</td></tr><tr><td>§4.5 mention pill</td><td>Tiny rounded pill with avatar/icon + name. Bots use a distinct icon + surface tint so users can see at a glance that a mention will dispatch to a runtime, not the LLM</td><td>Rox 438aaaec inline mentions</td></tr><tr><td>§4.5 mention picker</td><td>Sectioned: Bots → Documents → Members. Keyboard-first; arrow keys traverse cross-section; Esc closes</td><td>(cross-product convention)</td></tr></tbody></table><h2 id="_8-open-follow-up" tabindex="-1">8. Open follow-up <a class="header-anchor" href="#_8-open-follow-up" aria-label="Permalink to &quot;8. Open follow-up&quot;">​</a></h2><ul><li><strong>Density tokens.</strong> None of the surveyed UIs match the 14px-base density we want; most run at 15–16px. Our lock pass needs to settle on a token table independently. Survey of Linear / Height / Cursor (not in Refero today) is needed before the @soma/ui scaffold task.</li><li><strong>Multi-panel split.</strong> Hello Ivy and Rox both show a single right panel. We didn&#39;t find a clean reference for a <em>user-driven horizontal split inside the right area</em>. The closest analog is VS Code&#39;s editor groups — worth pulling once we start the <code>PanelContainer</code> component.</li><li><strong>Typing popup window</strong>. No useful Refero result for a small companion window adjunct to a main app. We&#39;ll design this against the constraint (always-on-top toggle, minimum size, no chrome past title bar) rather than from inspiration.</li></ul><hr><p><em>Next pass after this lands: revise PRD §4.5 to move backend switcher to composer footer; update §4.4 step 2 wording to reference the locked scoped-cards pattern; then promote the locked rows above into ADR-0005.</em></p>',41)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
